-- 📋 KPI Standard 2026 — ทะเบียน KPI มาตรฐานรายหน่วยงาน (Main project)
--    ewhdfqwfwofivojtsizn · ชื่อในจอ Supabase = "MAIN"              2026-09-21
--
-- ที่มา: `KPI Guideline 2026 (as of 29.01.2026)` หน้า 7-18 — ส่วนที่ 2 "KPI Standard 2026"
--   จัดทำโดย Ms. Sasiwimol Aryupantewan (Internal Audit & Analysis Manager)
--   👉 รายละเอียด + ตารางเทียบ: docs/OBEYA-KPI-SOURCES.md §15
--
-- ทำไมต้องมีตารางนี้แยกจาก `kpi_catalog`:
--   `kpi_catalog` = "ชื่อ KPI ที่ระบบนี้ใช้" (ผู้ใช้แก้ได้ · `kpi_definitions.catalog_id` ชี้มา)
--   ตารางนี้    = "เอกสารอ้างอิงของกลุ่ม รายปี" อ่านอย่างเดียวในทางปฏิบัติ · 1 KPI โผล่ได้หลายหน่วยงาน
--   ⚠️ ถ้ายัดรวมกัน: `TS Academy training` มีครบทั้ง 24 หน่วยงาน ⇒ ทะเบียนชื่อจะมี 24 แถวซ้ำ
--      และ `catalog_id` จะกำกวมทันที — จึงแยกตาราง แล้วผูกกันด้วย `catalog_id` (nullable)
--
-- 🔴 กติกาการเลือกที่เอกสารเขียนไว้ตรงๆ:
--      `fixed`  = KPI บังคับของหน่วยงานนั้น ต้องมี
--      `choice` = เลือกได้
--      null     = แถวหัวข้อแม่ที่ไม่มีคะแนนเอง (เช่น "Activity" ที่มีลูกเป็น QCC / Engineering Day)
--   แต่ละหน่วยงาน = หยิบ `fixed` ทั้งหมด + ติ๊ก `choice` เท่าที่ต้องการ แล้วถ่วงน้ำหนักให้รวม 50
--
-- ⚠️ `seq` = "เลขข้อที่พิมพ์บนเอกสาร" ใช้แสดงผลเท่านั้น **ห้ามใช้เป็นคีย์**
--    เอกสารต้นฉบับพิมพ์เลขซ้ำจริง 1 จุด: หน่วยงาน `Production` มีข้อ "6" สองแถว
--    (Cost Reduction · Day Sales of Inventory) ⇒ คีย์เรียงลำดับใช้ `sort_order` แทน
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists kpi_standard_items (
  id           uuid primary key default gen_random_uuid(),
  year         int  not null,
  std_unit     text not null,                 -- หน่วยงานมาตรฐานตามเอกสาร เช่น 'Production'
  seq          text not null,                 -- เลขข้อที่พิมพ์บนใบ ('1' · '11.1') — แสดงผลเท่านั้น
  sort_order   int  not null,                 -- ลำดับจริงในตาราง (คีย์เรียง · seq ซ้ำได้)
  perspective  text not null check (perspective in ('financial','customer','internal','learning')),
  topic        text not null,
  formula_text text,
  requirement  text check (requirement in ('fixed','choice')),   -- null = แถวหัวข้อแม่
  catalog_id   uuid references kpi_catalog(id) on delete set null,
  note         text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create unique index if not exists kpi_standard_items_uniq on kpi_standard_items (year, std_unit, sort_order);
create index if not exists kpi_standard_items_unit_idx on kpi_standard_items (year, std_unit);
create index if not exists kpi_standard_items_topic_idx on kpi_standard_items (topic);

drop trigger if exists trg_kpi_standard_items_updated on kpi_standard_items;
create trigger trg_kpi_standard_items_updated before update on kpi_standard_items
  for each row execute function fn_set_updated_at();

alter table kpi_standard_items enable row level security;
-- อ่านได้ทุกคนที่ล็อกอิน (เป็นเอกสารอ้างอิง) · เขียนเฉพาะคนที่มีสิทธิ์ปุ่มตั้งค่า KPI บนจอ
drop policy if exists kpi_standard_items_read  on kpi_standard_items;
drop policy if exists kpi_standard_items_write on kpi_standard_items;
create policy kpi_standard_items_read  on kpi_standard_items for select using (true);
create policy kpi_standard_items_write on kpi_standard_items for all
  using (has_perm('kpi:manage')) with check (has_perm('kpi:manage'));

-- จำว่านิยาม KPI แถวนี้ถูกสร้างจาก "หน่วยงานมาตรฐาน" ไหน (ใช้ตอน sync เติมข้อ fixed ที่ขาด)
alter table kpi_definitions add column if not exists std_unit text;

delete from kpi_standard_items where year = 2026;

